export { CreateFakeMicrophoneCapture };

export type EventDirection = "incoming" | "outgoing";

export const DEFAULT_REALTIME_MODEL = "gpt-realtime-2";

export interface RealtimeEvent
{
  type: string;
  [key: string]: unknown;
}

export interface ToolRuntimeContext
{
  sessionId: string;
  toolCallId: string;
  metadata?: Record<string, unknown>;
  log?: (message: string, fields?: Record<string, unknown>) => void;
}

export interface ToolDefinition<TArgs = unknown, TResult = unknown>
{
  name: string;
  description?: string;
  inputSchema: Record<string, unknown>;
  callback: (args: TArgs, ctx: ToolRuntimeContext) => Promise<TResult> | TResult;
}

export interface ToolCallSet
{
  name?: string;
  tools: ToolDefinition[];
}

export interface ConversationEventInfo
{
  sessionId: string;
  direction: EventDirection;
}

export type ConversationEventCallback = (
  event: RealtimeEvent,
  info: ConversationEventInfo,
) => void;

export type AgentEventCallback = (
  event: RealtimeEvent,
  info: ConversationEventInfo,
) => void;

export type ToolLifecyclePhase = "queued" | "started" | "succeeded" | "failed";

export interface ToolLifecycleNotification
{
  sessionId: string;
  toolCallId: string;
  toolName: string;
  phase: ToolLifecyclePhase;
  error?: string;
}

export type ToolLifecycleCallback = (notification: ToolLifecycleNotification) => void;

export type SessionEndedCallback = (info: {
  sessionId: string;
  reason: string;
  session: SessionRow;
}) => void;

export type RealtimeAgentTurnMode =
  | {
      type: "server_vad";
      silenceDurationMs?: number;
      threshold?: number;
      prefixPaddingMs?: number;
      createResponse?: boolean;
      interruptResponse?: boolean;
    }
  | {
      type: "manual";
    };

export type ResponseQueuePolicy = "enqueue" | "reject" | "cancel_current";

export interface QueueRequestOptions
{
  queuePolicy?: ResponseQueuePolicy;
}

export interface CreateResponseOptions extends QueueRequestOptions
{
  response?: Record<string, unknown>;
}

export interface SendMessageOptions extends QueueRequestOptions
{
  createResponse?: boolean;
  previousItemId?: string;
}

export interface QueuedEventResult
{
  status: "sent" | "queued" | "rejected" | "cancelled";
  reason?: string;
}

export interface StructuredContextMessage
{
  kind: string;
  source: "vscode" | "language_server" | "tool" | "system";
  payload: Record<string, unknown>;
  summary?: string;
}

export interface AgentStartConfig
{
  systemPrompt: string;
  initialContext: string;
  toolCallSet: ToolCallSet;
  model?: string;
  turnMode?: RealtimeAgentTurnMode;
  responseAfterToolOutput?: boolean;

  summary?: string;
}

export interface AgentStartConfig
{
  systemPrompt: string;
  initialContext: string;
  toolCallSet: ToolCallSet;
  model?: string;
  turnMode?: RealtimeAgentTurnMode;
  responseAfterToolOutput?: boolean;
  onConversationEvent?: ConversationEventCallback;
  onEvent?: AgentEventCallback;
  onToolLifecycle?: ToolLifecycleCallback;
  onSessionEnded?: SessionEndedCallback;
}

export interface AgentSessionDeps
{
  apiKey: string;
  safetyIdentifier?: string;
  baseUrl?: string;
  database?: import("./persistence/db.js").RealtimeAgentDb;
  webSocketFactory?: WebSocketFactory;
}

export interface RealtimeAgentSession
{
  readonly sessionId: string;
  sendAudioFrame(pcmBase64OrBuffer: string | Buffer): void;
  commitAudio(options?: QueueRequestOptions): Promise<QueuedEventResult>;
  createResponse(options?: CreateResponseOptions): Promise<QueuedEventResult>;
  commitAudioAndCreateResponse(options?: CreateResponseOptions): Promise<QueuedEventResult>;
  sendTextMessage(text: string, options?: SendMessageOptions): Promise<QueuedEventResult>;
  sendStructuredContext(
    message: StructuredContextMessage,
    options?: SendMessageOptions,
  ): Promise<QueuedEventResult>;
  sendRealtimeEvent(event: RealtimeEvent, options?: QueueRequestOptions): Promise<QueuedEventResult>;
  clearAudioBuffer(options?: QueueRequestOptions): Promise<QueuedEventResult>;
  stop(reason: string): Promise<SessionRow>;
}

export interface DatabaseConfig
{
  path?: string;
  ensureDirectory?: boolean;
}

export interface CreateSessionInput
{
  systemPrompt: string;
  initialContext: string;
  toolCallSetName?: string | null;
  toolNames: string[];
  model: string;
  sessionConfig: Record<string, unknown>;
}

export interface SessionRow
{
  id: string;
  createdAt: string;
  endedAt: string | null;
  endedReason: string | null;
  systemPrompt: string;
  initialContext: string;
  toolCallSetName: string | null;
  toolNamesJson: string;
  model: string;
  sessionConfigJson: string;
}

export interface EventRow
{
  id: number;
  sessionId: string;
  createdAt: string;
  direction: EventDirection;
  eventType: string;
  eventJson: string;
  isAudioBufferAppend: boolean;
}

export interface PersistEventInput
{
  sessionId: string;
  direction: EventDirection;
  event: RealtimeEvent;
}

export type IncomingEventClass =
  | "session_lifecycle"
  | "input_audio_turn"
  | "transcription"
  | "text_output"
  | "tool_call"
  | "error"
  | "unknown";

export type OutgoingEventClass =
  | "session_config"
  | "conversation_input"
  | "tool_output"
  | "response_trigger"
  | "audio_buffer_append"
  | "unknown";

export interface RealtimeWebSocketLike
{
  readonly readyState: number;
  send(data: string): void;
  close(code?: number, reason?: string): void;
  on(event: "open", listener: () => void): void;
  on(event: "message", listener: (data: string) => void): void;
  on(event: "error", listener: (error: Error) => void): void;
  on(event: "close", listener: (code: number, reason: string) => void): void;
  off(event: "open", listener: () => void): void;
  off(event: "message", listener: (data: string) => void): void;
  off(event: "error", listener: (error: Error) => void): void;
  off(event: "close", listener: (code: number, reason: string) => void): void;
}

export interface WebSocketConnectOptions
{
  headers: Record<string, string>;
}

export type WebSocketFactory = (
  url: string,
  options: WebSocketConnectOptions,
) => RealtimeWebSocketLike;

export interface RealtimeClientOptions
{
  apiKey: string;
  model: string;
  safetyIdentifier?: string;
  baseUrl?: string;
  webSocketFactory?: WebSocketFactory;
}

export type RealtimeEventHandler = (event: RealtimeEvent) => void;
export type RealtimeErrorHandler = (error: Error) => void;
export type RealtimeCloseHandler = (code: number, reason: string) => void;

export interface ClassifiedIncomingEvent
{
  event: RealtimeEvent;
  eventClass: IncomingEventClass;
}

export interface ClassifiedOutgoingEvent
{
  event: RealtimeEvent;
  eventClass: OutgoingEventClass;
}

export interface EventRouterCallbacks
{
  onConversationEvent?: ConversationEventCallback;
  onEvent?: AgentEventCallback;
  onSessionLifecycle?: RealtimeEventHandler;
  onInputAudioTurn?: RealtimeEventHandler;
  onTranscription?: RealtimeEventHandler;
  onTextOutput?: RealtimeEventHandler;
  onToolCall?: RealtimeEventHandler;
  onErrorEvent?: RealtimeEventHandler;
  onUnknownIncoming?: RealtimeEventHandler;
  onSessionConfig?: RealtimeEventHandler;
  onConversationInput?: RealtimeEventHandler;
  onToolOutput?: RealtimeEventHandler;
  onResponseTrigger?: RealtimeEventHandler;
  onAudioBufferAppend?: RealtimeEventHandler;
  onUnknownOutgoing?: RealtimeEventHandler;
}

export interface EventRouterOptions extends EventRouterCallbacks
{
  sessionId: string;
  eventsRepo: import("./persistence/events_repo.js").EventsRepo;
}

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import path from "node:path";

import { FindRepositoryRoot } from "realtime-agent-lib";

export interface WorkspaceFolderLike
{
  uri: { fsPath: string };
}

const x_realtimeAgentProjectRelative = "projects/realtime-agent";
const x_apiKeysRelative = "config/api_keys.json";
const x_runtimeLogRelative = "logs/realtime-agent/vscode-extension.jsonl";

export function FindSheafRepositoryRoot(startPath: string): string | undefined
{
  const root = FindRepositoryRoot(startPath);
  if (root === undefined)
  {
    return undefined;
  }

  const projectPath = path.join(root, x_realtimeAgentProjectRelative);
  if (!existsSync(projectPath))
  {
    return undefined;
  }

  return root;
}

export function FindSheafRepositoryRootFromWorkspaceFolders(
  folders: readonly WorkspaceFolderLike[],
): string | undefined
{
  for (const folder of folders)
  {
    const root = FindSheafRepositoryRoot(folder.uri.fsPath);
    if (root !== undefined)
    {
      return root;
    }
  }

  return undefined;
}

export function ResolveExtensionRuntimeLogPath(repoRoot: string): string
{
  return path.join(repoRoot, x_runtimeLogRelative);
}

export async function LoadOpenAiApiKeyFromRepoConfig(
  repoRoot: string,
): Promise<{ apiKey?: string; error?: string }>
{
  const apiKeysPath = path.join(repoRoot, x_apiKeysRelative);

  try
  {
    const content = await readFile(apiKeysPath, "utf8");
    const parsed = JSON.parse(content) as { openai_api_key?: unknown };
    const apiKey =
      typeof parsed.openai_api_key === "string" ? parsed.openai_api_key.trim() : "";

    if (apiKey.length > 0)
    {
      return { apiKey };
    }

    return {};
  }
  catch (error)
  {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === "ENOENT")
    {
      return {};
    }

    const message = error instanceof Error ? error.message : String(error);
    return { error: `Failed to load ${apiKeysPath}: ${message}` };
  }
}
